  tools.exec_command({cmd:"rg --files --hidden -g 'AGENTS.md' -g 'README*' -g 'pyproject.toml' -g 'package.json' -g 'requirements*.txt' -g 'Dockerfile*' -g 'docker-compose*' -g '.env*' -g '!node_modules' -g '!.git' | sort; git status --short --branch; ls -la",workdir:"/Users/viniciussiegle/Documents/EHL-Hackathon/The-Last-Team",yield_time_ms:10000,max_output_tokens:6000})
