for (let i = 0; i < results.length; i++) text(JSON.stringify({task:i===0?"fetch llms.txt":"repo inventory",result:results[i]}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"atira --version; atira status",workdir:"/Users/viniciussiegle/Documents/EHL-Hackathon/The-Last-Team",yield_time_ms:10000,max_output_tokens:4000}),
  tools.exec_command({cmd:"uv --version; python3 --version; node --version",workdir:"/Users/viniciussiegle/Documents/EHL-Hackathon/The-Last-Team",yield_time_ms:10000,max_output_tokens:2000}),
  tools.exec_command({cmd:"sed -n '1,280p' tests/test_kit.py; git log -5 --oneline --decorate",workdir:"/Users/viniciussiegle/Documents/EHL-Hackathon/The-Last-Team",yield_time_ms:10000,max_output_tokens:5000})
]);
for (let i = 0; i < results.length; i++) text(JSON.stringify({task:["atira status","local runtimes","tests and history"][i],result:results[i]}));

const results = await Promise.allSettled([
