item.aggregated_output:
  name: "get_run",
  title: "Get a run",
  description:
    "One run in full: status, phase and failure, its place in the queue or the free models' warm-up while it waits, phase starts on the run's clock, the package, LLM calls by model with failures and queue waits, the score with points per field (test runs), the recordings, the answer it entered, and the run page URL (?t=mm:ss opens the replay there). About 1–2k tokens.",
  inputSchema: { type: "object", properties: { run_id: RUN_ID }, required: ["run_id"], additionalProperties: false },
  annotations: READ,
  async run(args, session) {
    const ctx = signedIn()
    const runId = await mcpRunId(ctx, args.run_id)
    const facts = await runFacts(ctx, runId)
    const { detail, end, now } = facts
    const calls = await runCalls(ctx, runId).then(
      (result) => result.calls,
      () => null,
    )
    const live = calls ? null : await getJson(ctx, `/runs/${enc(runId)}/live.json`, { auth: false }).catch(() => null)
    const score = detail.score
    const points = score?.breakdown ? breakdownPoints(score.breakdown) : []
    const videos = detail.videos ?? (detail.has_video ? [{ browser: 1, duration_ms: detail.video_duration_ms }] : [])
    const lines = [
      ...(await runHead(ctx, facts)),
      ...(calls
        ? llmLines(calls, now)
        : [
            `LLM: ${counted(detail.calls, "call")}, ${usd(detail.cost_micro_usd)}, ${num(detail.input_tokens)} in / ${num(detail.output_tokens)} out tokens`,
