async function logs({ args, options, json }) {
  const ctx = context()
  const runId = args[0].startsWith("reh_") ? await rehearsalRun(ctx, args[0]) : args[0]
  return followLogs(ctx, runId, { follow: options.follow, json })
}

/** Prints a run's logs from the start; following, polls with a growing pause until the run has ended. */
async function followLogs(ctx, runId, { follow, json }) {
  const minimum = Math.max(10, Number(process.env.ATIRA_POLL_MS) || 1000)
  let delay = minimum
  let cursor = 0
  let waiting = null
  for (;;) {
    const page = await getJson(ctx, `/v1/runs/${enc(runId)}/logs?after=${cursor}`)
    for (const chunk of page.chunks)
      process.stdout.write(
        json ? `${JSON.stringify({ at: chunk.at, stream: chunk.stream, text: chunk.text })}\n` : chunk.text,
      )
    cursor = page.cursor
