      }
      if (lines.length) return [mcpText(`${lines.map(logLine).join("\n")}\n${footer}`)]
      // nothing: say where the logs are, so the next query lands
      const first = await logPage(ctx, runId, { limit: 1 }).catch(() => null)
      const start = first?.lines[0]?.t
      const span =
      const { detail, end, now } = facts
      const calls = await runCalls(ctx, runId).then(
        (result) => result.calls,
        () => null,
      )
      const live = calls ? null : await getJson(ctx, `/runs/${enc(runId)}/live.json`, { auth: false }).catch(() => null)
      const score = detail.score
      const points = score?.breakdown ? breakdownPoints(score.breakdown) : []
      const videos = detail.videos ?? (detail.has_video ? [{ browser: 1, duration_ms: detail.video_duration_ms }] : [])
      const lines = [
        ...(await runHead(ctx, facts)),
        ...(calls
          ? llmLines(calls, now)
          : [
              `LLM: ${counted(detail.calls, "call")}, ${usd(detail.cost_micro_usd)}, ${num(detail.input_tokens)} in / ${num(detail.output_tokens)} out tokens`,
              ...(live?.models ?? []).map(
                (model) =>
                  `  ${model.model ? `${model.provider}/${model.model}` : `${model.provider} (failed before naming a model)`}: ${counted(model.calls, "call")}, ${usd(model.cost_micro_usd)}, ${num(model.input_tokens)} in / ${num(model.output_tokens)} out`,
              ),
            ]),
        score
          ? `Score: quality ${quality(score.quality)}, ${score.eligible ? "eligible" : "not eligible"}, cost ${usd(score.cost_micro_usd)}, time ${clock(score.duration_ms)}, cost × time ${costTimeText(costTime(score.cost_micro_usd, score.duration_ms))}`
          : "Score: none yet",
        points.length
          ? `Points per field:\n${points.map(([field, value, got]) => `  ${field}: ${value}${got === undefined ? "" : ` (entered ${shortValue(got)})`}`).join("\n")}`
          : null,
        videos.length
          ? `Recordings: ${videos.map((video) => `browser ${video.browser} (${clock(video.duration_ms)})`).join(", ")}; see run_screenshot`
          : `Recordings: none${!runFinalized(facts) ? " yet (available after collection; run_screenshot shows the latest screen meanwhile)" : ""}`,
        detail.has_answer && detail.answer !== null
          ? `Answer entered:\n${truncate(JSON.stringify(detail.answer), 4000)}`
          : `Answer: ${detail.has_answer ? "entered" : "none"}`,
        `Run page: ${runPage(ctx, runId)}${end === null || detail.finished_at === null ? "" : ` · its end: ${runPage(ctx, runId, end)}`}`,
        detail.status === "failed" ? "Next: diagnose_run for why it failed and what to do." : null,
      ]
      return [
        mcpText(lines.filter((line) => line !== null).join("\n")),
        ...mcpLink(session, runPage(ctx, runId), runId, "The run page: live view, logs and replay", "text/html"),
      ]
    },
  },
